/* The status and results of a reply to idltest_sums_send (read with
 * idl_reply_read). The reply's handles are taken in every case: moved to
 * the results, or closed (on a failure, or for a NULL result). */
static inline status_t idltest_sums_result(const void *idl_rep, struct idl_msg *idl_m, uint64_t *out_total, uint8_t *out_tag, uint32_t out_b[4], uint32_t *out_b_len, int64_t out_c[2], uint32_t *out_c_len)
{
    const struct idltest_sums_rep *idl_r = (const struct idltest_sums_rep *)idl_rep;
    uint32_t idl_o = sizeof(*idl_r);
    status_t idl_st = idl_rep_status_var(idl_rep, idl_m->n, sizeof(*idl_r));
    const void *idl_p0 = NULL;
    uint32_t idl_l0 = 0;
    const void *idl_p1 = NULL;
    uint32_t idl_l1 = 0;
    if (idl_st == OK && !idl_get(idl_rep, idl_m->n, &idl_o, 4, 4, &idl_p0, &idl_l0))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !idl_get(idl_rep, idl_m->n, &idl_o, 2, 8, &idl_p1, &idl_l1))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && idl_o != idl_m->n)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && idl_m->nh != 0)
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    idl_m->nh = 0;
    if (out_total)
        *out_total = idl_r->total;
    if (out_tag)
        *out_tag = idl_r->tag;
    if (out_b) {
        if (idl_l0)
            __builtin_memcpy(out_b, idl_p0, idl_l0 * 4);
    }
    if (out_b_len)
        *out_b_len = idl_l0;
    if (out_c) {
        if (idl_l1)
            __builtin_memcpy(out_c, idl_p1, idl_l1 * 8);
    }
    if (out_c_len)
        *out_c_len = idl_l1;
    return OK;
}

/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with idltest_reply_<method> (now, or later from anywhere). */
struct idltest_ops {
    status_t (*echo)(void *ctx, uint32_t value, uint32_t *out_value);
    status_t (*wait)(void *ctx, struct idl_txn idl_txn, uint32_t key, uint32_t *out_key, uint32_t *out_order);
    status_t (*release)(void *ctx, uint32_t key, uint32_t *out_woken);
    status_t (*make_vmo)(void *ctx, struct idl_txn idl_txn, uint32_t key, uint32_t size, handle_t *out_vmo, uint32_t *out_size_back);
    status_t (*bytes)(void *ctx, uint32_t tag, const uint8_t *data, uint32_t data_len, uint8_t *out_data, uint32_t *out_data_len, uint32_t *out_tag);
    status_t (*greet)(void *ctx, const char *name, uint32_t name_len, const char *word, uint32_t word_len, char *out_text, uint32_t *out_text_len);
    status_t (*later_text)(void *ctx, struct idl_txn idl_txn, uint32_t key, char *out_name, uint32_t *out_name_len, uint8_t *out_extra, uint32_t *out_extra_len);
    status_t (*broken)(void *ctx, uint32_t how, char *out_text, uint32_t *out_text_len, uint8_t *out_data, uint32_t *out_data_len);
    status_t (*sums)(void *ctx, uint8_t tag, const uint16_t *a, uint32_t a_len, const uint32_t *b, uint32_t b_len, const uint64_t *c, uint32_t c_len, uint64_t *out_total, uint8_t *out_tag, uint32_t *out_b, uint32_t *out_b_len, int64_t *out_c, uint32_t *out_c_len);
};

/* Answer the idltest.echo request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t idltest_reply_echo(struct idl_txn idl_txn, status_t idl_st, uint32_t value)
{
    struct idltest_echo_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    idl_r.value = value;
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

/* Answer the idltest.wait request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t idltest_reply_wait(struct idl_txn idl_txn, status_t idl_st, uint32_t key, uint32_t order)
{
    struct idltest_wait_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    idl_r.key = key;
    idl_r.order = order;
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

